import{_ as t,o as r,c as a,a2 as n}from"./chunks/framework.DdtnLau3.js";const h=JSON.parse('{"title":"Harness Specification","description":"","frontmatter":{},"headers":[],"relativePath":"spec/harness.md","filePath":"spec/harness.md"}'),o={name:"spec/harness.md"};function i(s,e,c,d,p,l){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="harness-specification" tabindex="-1">Harness Specification <a class="header-anchor" href="#harness-specification" aria-label="Permalink to &quot;Harness Specification&quot;">​</a></h1><h2 id="current-execution-layer" tabindex="-1">Current execution layer <a class="header-anchor" href="#current-execution-layer" aria-label="Permalink to &quot;Current execution layer&quot;">​</a></h2><p>The Harness runs in <code>apps/agentd</code> inside each Work&#39;s Agent container. It uses the Pi Agent SDK for model calls, tool execution, resource loading, Sessions, Runs, and SDK history. Core remains the lifecycle and authorization authority.</p><p><code>AGENTS.md</code>, selected Skills, and Pi Packages form Work-owned context. The running Harness loads captured active configuration. Edits prepare desired state; explicit Apply changes what is loaded. Source edits do not hot-reload the current Run.</p><p>Only one Run is active per Work. Its model execution happens in the Agent; the browser and CLI do not proxy model calls. Model credentials supplied by Core remain private and are excluded from <code>.work</code> packages.</p><h2 id="current-context-and-history" tabindex="-1">Current context and history <a class="header-anchor" href="#current-context-and-history" aria-label="Permalink to &quot;Current context and history&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Role</th></tr></thead><tbody><tr><td><code>AGENTS.md</code></td><td>Work-specific instructions.</td></tr><tr><td>Skills</td><td>Selected instruction resources.</td></tr><tr><td>Pi Packages</td><td>Prepared extensions, tools, prompts, themes, and other SDK resources.</td></tr><tr><td>Sessions and Runs</td><td>Conversations, execution records, and original SDK history.</td></tr><tr><td>Active / desired context</td><td>Loaded configuration versus pending changes.</td></tr></tbody></table><p>Core validates package compatibility before activation. The current portable package preserves prepared artifacts and dependencies; import does not rerun npm, Git, or package code to reconstruct them.</p><h2 id="experimental-piwork-brain" tabindex="-1">Experimental: <code>piwork-brain</code> <a class="header-anchor" href="#experimental-piwork-brain" aria-label="Permalink to &quot;Experimental: `piwork-brain`&quot;">​</a></h2><p>The default brain is an ordinary Pi extension package. Core seeds it once; administrator changes are not reset on later starts. New default Works select it unless configuration explicitly omits packages.</p><p>Its implemented flow has four important boundaries:</p><ol><li><strong>Observe and act:</strong> the Harness reads a Service capability contract, observes state, records a stable Action identity, and sends the declared input and expected state version.</li><li><strong>Verify:</strong> successful prose or a finished Run is insufficient. Synchronous changes require actual observation; asynchronous jobs retain the original Action/Job references for later verification.</li><li><strong>Retain experience:</strong> candidate rules become an effective experience version only after successful verification of the associated task. An active Run keeps its adopted version; the next execution can use the new one.</li><li><strong>Prepare and Apply:</strong> editable brain source can be captured and prepared as a candidate. The user explicitly Applies it, followed by the required behavior checks. Preparation or successful loading alone does not prove that the change works.</li></ol><p>Service events can request bounded automatic execution when the Work is ready and has no active Run. Requests, cancellation, retry, and recovery have stable identities and deadlines. Restarting does not replay an unknown mutation.</p><p>Export preserves this durable history. Imported events and requests remain historical and cannot schedule or replay effects from the source installation.</p><h2 id="future-direction" tabindex="-1">Future direction <a class="header-anchor" href="#future-direction" aria-label="Permalink to &quot;Future direction&quot;">​</a></h2><p>A Harness increasingly adapted to its Work and user is the product direction. The current system does not guarantee unrestricted autonomous learning, invisible self-upgrades, or that every application exposes structured capabilities.</p><p>The authoritative sources are the <a href="https://github.com/pphboy/piwork/blob/main/docs/piwork-brain.md" target="_blank" rel="noreferrer">brain workflow</a>, <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/piwork-brain/spec.md" target="_blank" rel="noreferrer">brain spec</a>, <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/agent-conversation/spec.md" target="_blank" rel="noreferrer">agent-conversation spec</a>, and <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/pi-package-activation/spec.md" target="_blank" rel="noreferrer">package activation spec</a>.</p>',17)])])}const b=t(o,[["render",i]]);export{h as __pageData,b as default};
